#pragma once
#include <array>
#include <cstdint>
namespace ks {class StateAuditionTask final {public:enum class Stage {Poll,CompareOn,AdmitOn,SetOnTarget,ClearOnPayload,SetOnMode,ConfigureOn,SetOnNote,SetOnVelocity,TailOn,CompareOff,AdmitOff,SetOffTarget,ClearOffPayload,SetOffMode,ConfigureOff,SetOffNote,SetOffVelocity,TailOff,Return,AwaitPoll,AwaitConfigure,AwaitNote,Complete};enum class Event {None,On,Off};Stage stage()const{return phase_;}Stage resumeStage()const{return resume_;}bool complete()const{return phase_==Stage::Complete;}bool awaitingPoll()const{return phase_==Stage::AwaitPoll;}bool awaitingConfigure()const{return phase_==Stage::AwaitConfigure;}bool awaitingNote()const{return phase_==Stage::AwaitNote;}Event event()const{return event_;}static constexpr unsigned note(){return 60;}unsigned velocity()const{return event_==Event::On?127:64;}unsigned mode()const{return event_==Event::On?1:2;}bool resumePoll(uint8_t state){if(!awaitingPoll())return false;state_=state;phase_=Stage::CompareOn;return true;}bool resumeConfigure(){if(!awaitingConfigure())return false;phase_=resume_;return true;}bool retireNote(){if(!awaitingNote())return false;phase_=Stage::Complete;return true;}
 unsigned nextClocks()const{constexpr std::array<unsigned,20> costs{{20,3,3,6,3,3,20,3,3,8,3,3,6,3,3,20,3,3,8,17}};return unsigned(phase_)<costs.size()?costs[unsigned(phase_)]:0;}unsigned advanceBefore(unsigned available){unsigned used=0;while(const auto c=nextClocks()){if(c>available-used)break;switch(phase_){case Stage::Poll:phase_=Stage::AwaitPoll;break;case Stage::AdmitOn:if(state_==32){event_=Event::On;next();}else phase_=Stage::CompareOff;break;case Stage::AdmitOff:if(state_==16){event_=Event::Off;next();}else phase_=Stage::Return;break;case Stage::ConfigureOn:resume_=Stage::SetOnNote;phase_=Stage::AwaitConfigure;break;case Stage::ConfigureOff:resume_=Stage::SetOffNote;phase_=Stage::AwaitConfigure;break;case Stage::TailOn:case Stage::TailOff:phase_=Stage::AwaitNote;break;case Stage::Return:phase_=Stage::Complete;break;default:phase_=Stage(unsigned(phase_)+1);break;}used+=c;}return used;}
private:void next(){phase_=Stage(unsigned(phase_)+1);}Stage phase_=Stage::Poll,resume_=Stage::Complete;Event event_=Event::None;uint8_t state_=0;};}
